import { RADIUS_REM, TOKENS, isThemed, resolve } from "./tokens.ts";

const BANNER = `/*
 * Generated by packages/tokens/scripts/generate.mjs — do not edit.
 *
 * Edit packages/tokens/src/tokens.ts and re-run:
 *   npm run tokens:generate
 */
`;

const RADIUS_PX = RADIUS_REM * 16;

const radiusScale = {
  sm: RADIUS_PX - 2,
  md: RADIUS_PX,
  lg: RADIUS_PX + 2,
  xl: RADIUS_PX + 4,
  "2xl": RADIUS_PX + 6,
  "3xl": RADIUS_PX + 8,
  "4xl": RADIUS_PX + 10,
};

const camel = (name: string) => name.replace(/-([a-z0-9])/g, (_, c: string) => c.toUpperCase());

export function buildCss(): string {
  let out = `${BANNER}\n:root {\n  --radius: ${RADIUS_REM}rem;\n\n`;
  for (const token of TOKENS) out += `  --${token.name}: ${resolve(token.name, "light")};\n`;
  out += "}\n\n.dark {\n";
  for (const token of TOKENS.filter((t) => isThemed(t.value))) {
    out += `  --${token.name}: ${resolve(token.name, "dark")};\n`;
  }
  out += "}\n";
  return out;
}

export function buildNativeCss(): string {
  let out = `${BANNER}\n:root {\n`;
  for (const [name, px] of Object.entries(radiusScale)) out += `  --radius-${name}: ${px}px;\n`;
  out += "\n";
  for (const token of TOKENS) out += `  --${token.name}: ${resolve(token.name, "light")};\n`;
  out += "}\n\n@media (prefers-color-scheme: dark) {\n  :root {\n";
  for (const token of TOKENS.filter((t) => isThemed(t.value))) {
    out += `    --${token.name}: ${resolve(token.name, "dark")};\n`;
  }
  out += "  }\n}\n";
  return out;
}

export function buildNativeTs(): string {
  let out = `${BANNER}\n/* eslint-disable */\n\n`;
  for (const theme of ["light", "dark"] as const) {
    out += `export const ${theme}Colors = {\n`;
    for (const token of TOKENS)
      out += `  "${camel(token.name)}": "${resolve(token.name, theme)}",\n`;
    out += "} as const;\n\n";
  }
  out += "export type ColorName = keyof typeof lightColors;\n\n";
  out += "export const colors = { light: lightColors, dark: darkColors } as const;\n\n";
  out += "export const cssVarNames = {\n";
  for (const token of TOKENS) out += `  "${camel(token.name)}": "--${token.name}",\n`;
  out += "} as const satisfies Record<ColorName, string>;\n\n";
  out += `export const RADIUS_BASE_PX = ${RADIUS_PX};\n\n`;
  out += "export const radius = {\n";
  for (const [name, px] of Object.entries(radiusScale)) out += `  "${name}": ${px},\n`;
  out += "} as const;\n";
  return out;
}

export const artifacts = {
  "tokens.css": buildCss,
  "tokens.native.css": buildNativeCss,
  "tokens.native.ts": buildNativeTs,
} as const;
